using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer;

/// <summary>
/// MCP tools that wrap a weather REST API.
/// The SDK discovers methods decorated with [McpServerTool] and uses
/// [Description] attributes to provide LLM-friendly metadata.
/// Constructor parameters are resolved from DI automatically.
/// </summary>
[McpServerToolType]
public sealed class WeatherTools
{
    private readonly HttpClient _http;

    // HttpClient is injected via DI (IHttpClientFactory named client)
    public WeatherTools(HttpClient httpClient)
    {
        _http = httpClient;
    }

    [McpServerTool, Description("Get the current weather forecast for a city.")]
    public async Task<string> GetWeather(
        [Description("City name, e.g. 'Seattle'")] string city,
        CancellationToken cancellationToken = default)
    {
        var url = $"https://wttr.in/{Uri.EscapeDataString(city)}?format=j1";
        var response = await _http.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(
            await response.Content.ReadAsStreamAsync(cancellationToken),
            cancellationToken: cancellationToken);

        var current = doc.RootElement.GetProperty("current_condition")[0];
        var tempC = current.GetProperty("temp_C").GetString();
        var desc = current.GetProperty("weatherDesc")[0]
            .GetProperty("value").GetString();
        var humidity = current.GetProperty("humidity").GetString();

        return $"{city}: {tempC}°C, {desc}, Humidity {humidity}%";
    }

    [McpServerTool, Description("Get a 3-day weather forecast for a city.")]
    public async Task<string> GetForecast(
        [Description("City name")] string city,
        CancellationToken cancellationToken = default)
    {
        var url = $"https://wttr.in/{Uri.EscapeDataString(city)}?format=j1";
        var response = await _http.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(
            await response.Content.ReadAsStreamAsync(cancellationToken),
            cancellationToken: cancellationToken);

        var days = doc.RootElement.GetProperty("weather");
        var lines = new List<string>();
        foreach (var day in days.EnumerateArray())
        {
            var date = day.GetProperty("date").GetString();
            var maxC = day.GetProperty("maxtempC").GetString();
            var minC = day.GetProperty("mintempC").GetString();
            lines.Add($"{date}: {minC}–{maxC}°C");
        }

        return $"3-day forecast for {city}:\n{string.Join("\n", lines)}";
    }
}

