using McpServer;
using Microsoft.Extensions.DependencyInjection;
using ModelContextProtocol.Server;

var builder = McpServerApp.CreateBuilder();

// Register HttpClient for the tool class via IHttpClientFactory
builder.Services.AddHttpClient<WeatherTools>(client =>
{
    client.DefaultRequestHeaders.Add("User-Agent", "McpWeatherServer/1.0");
});

// Register tools from the assembly (discovers [McpServerToolType] classes)
builder.Services.AddMcpServerTools<WeatherTools>();

// Use stdio transport (reads JSON-RPC from stdin, writes to stdout)
builder.Services.AddMcpServer(options =>
{
    options.ServerInfo = new()
    {
        Name = "weather-server",
        Version = "1.0.0"
    };
    options.Capabilities = new()
    {
        Tools = new() { }
    };
}).WithStdioTransport();

await builder.Build().RunAsync();

