2. using System.Text.Json;
3. using ModelContextProtocol.Server;
4. 
5. namespace McpServer;
6. 
7. /// <summary>
8. /// MCP tools that wrap a weather REST API.
9. /// The SDK discovers methods decorated with [McpServerTool] and uses
10. /// [Description] attributes to provide LLM-friendly metadata.
11. /// Constructor parameters are resolved from DI automatically.
12. /// </summary>
13. [McpServerToolType]
14. public sealed class WeatherTools(HttpClient httpClient)
15. {
16.     private readonly HttpClient _http = httpClient;
17. 
18.     [McpServerTool, Description("Get the current weather forecast for a city.")]
19.     public async Task<string> GetWeather(
20.         [Description("City name, e.g. 'Seattle'")] string city,
21.         CancellationToken cancellationToken = default)
22.     {
23.         var url = $"https://wttr.in/{Uri.EscapeDataString(city)}?format=j1";
24.         var response = await _http.GetAsync(url, cancellationToken);
25.         response.EnsureSuccessStatusCode();
26. 
27.         using var doc = await JsonDocument.ParseAsync(
28.             await response.Content.ReadAsStreamAsync(cancellationToken),
29.             cancellationToken: cancellationToken);
30. 
31.         var current = doc.RootElement.GetProperty("current_condition")[0];
32.         var tempC = current.GetProperty("temp_C").GetString();
33.         var desc = current.GetProperty("weatherDesc")[0]
34.             .GetProperty("value").GetString();
35.         var humidity = current.GetProperty("humidity").GetString();
36. 
37.         return $"{city}: {tempC}°C, {desc}, Humidity {humidity}%";
38.     }
39. 
40.     [McpServerTool, Description("Get a 3-day weather forecast for a city.")]
41.     public async Task<string> GetForecast(
42.         [Description("City name")] string city,
43.         CancellationToken cancellationToken = default)
44.     {
45.         var url = $"https://wttr.in/{Uri.EscapeDataString(city)}?format=j1";
46.         var response = await _http.GetAsync(url, cancellationToken);
47.         response.EnsureSuccessStatusCode();
48. 
49.         using var doc = await JsonDocument.ParseAsync(
50.             await response.Content.ReadAsStreamAsync(cancellationToken),
51.             cancellationToken: cancellationToken);
52. 
53.         var days = doc.RootElement.GetProperty("weather");
54.         var lines = new List<string>();
55.         foreach (var day in days.EnumerateArray())
56.         {
57.             var date = day.GetProperty("date").GetString();
58.             var maxC = day.GetProperty("maxtempC").GetString();
59.             var minC = day.GetProperty("mintempC").GetString();
60.             lines.Add($"{date}: {minC}–{maxC}°C");
61.         }
62. 
63.         return $"3-day forecast for {city}:\n{string.Join("\n", lines)}";
64.     }
65. }
